<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class QualificationAssessment extends Model { use HasUuids; protected $guarded=[]; protected function casts():array{return ['readiness_score'=>'decimal:2','evaluated_at'=>'datetime','submitted_at'=>'datetime','assessed_at'=>'datetime'];} public function member():BelongsTo{return $this->belongsTo(Member::class);} public function framework():BelongsTo{return $this->belongsTo(QualificationFramework::class,'framework_id');} public function targetLevel():BelongsTo{return $this->belongsTo(QualificationFrameworkLevel::class,'target_level_id');} public function results():HasMany{return $this->hasMany(QualificationAssessmentResult::class,'assessment_id');} public function recommendations():HasMany{return $this->hasMany(QualificationRecommendation::class,'assessment_id')->orderBy('priority');} }
